  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.contact-form select {
  cursor: pointer;
  appearance: none;
  background-image: url('data:image/svg+xml;charset=UTF-8,<svg width="12" height="8" viewBox="0 0 12 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M1 1L6 6L11 1" stroke="%231a3a2e" stroke-width="2" stroke-linecap="round"/></svg>');
