  .emergency-card h2 {
    font-size: 1.25rem;
  }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .contact-form {
    padding: var(--spacing-md);
  }

  .form-row {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
